export function appendFeed(rows,entry,limit=80){const text=String(entry.text||'').trim().slice(0,220);if(!text)return rows;return [...rows,{channel:['drop','chat','story','system'].includes(entry.channel)?entry.channel:'system',text,author:String(entry.author||'').slice(0,24),time:entry.time||Date.now()}].slice(-limit);}
export function mountFeed(root,onFocus=()=>{}){const host=document.createElement('aside');host.className='gameFeed';host.setAttribute('aria-label','Chat local e registro de drops');host.innerHTML='<div class="dropFeed" aria-label="Últimos drops"><b>ESPÓLIO</b><div class="dropRows"></div></div><button class="feedToggle" aria-expanded="false">CHAT LOCAL · SOLO <span>＋</span></button><div class="chatExpanded" hidden><div class="feedTabs"><button data-feed="chat">Conversa local</button><button data-feed="drop">Drops</button><button data-feed="story">Crônicas</button></div><div class="chatRows" role="log" aria-label="Mensagens"></div><form class="chatForm"><input aria-label="Mensagem local" maxlength="180" placeholder="Mensagem local neste dispositivo"><button>Enviar</button></form><small>Alpha solo · mensagens não são enviadas a outros jogadores.</small></div>';root.append(host);let rows=[],channel='chat',author='Você';const q=s=>host.querySelector(s),render=()=>{q('.dropRows').replaceChildren(...rows.filter(r=>r.channel==='drop').slice(-2).map(r=>{const d=document.createElement('div');d.textContent=r.text;d.title=r.text;return d;}));q('.chatRows').replaceChildren(...rows.filter(r=>r.channel===channel).map(r=>{const d=document.createElement('p');if(r.author){const b=document.createElement('b');b.textContent=r.author+': ';d.append(b);}d.append(document.createTextNode(r.text));return d;}));q('.chatRows').scrollTop=q('.chatRows').scrollHeight;};const push=(channel,text)=>{rows=appendFeed(rows,{channel,text});render();};q('.feedToggle').onclick=()=>{const expanded=!host.classList.contains('expanded');host.classList.toggle('expanded',expanded);q('.chatExpanded').hidden=!expanded;q('.feedToggle').setAttribute('aria-expanded',String(expanded));if(expanded)onFocus();};host.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{channel=b.dataset.feed;render();});q('input').onfocus=onFocus;q('input').onkeydown=e=>e.stopPropagation();q('form').onsubmit=e=>{e.preventDefault();const input=q('input');if(!input.value.trim())return;rows=appendFeed(rows,{channel:'chat',text:input.value,author});input.value='';channel='chat';render();};return{push,reset(name){rows=[];author=name||'Você';render();},host};}
export function lootSnapshot(p){return{gold:p.gold||0,shards:p.shards||0,pots:{...p.pots},materials:{...p.materials},bag:new Set((p.bag||[]).map(i=>i.id))};}
export function lootDiff(before,p){const rows=[],rare=[],equipment=[];for(const i of p.bag||[])if(!before.bag.has(i.id))equipment.push(i.name+' · '+i.quality);const gold=(p.gold||0)-before.gold,shards=(p.shards||0)-before.shards;if(gold>0)rows.push(gold.toLocaleString('pt-BR')+' ouro');if(shards>0)rows.push('Cristais ×'+shards);for(const k of ['hp','mp']){const n=(p.pots?.[k]||0)-(before.pots[k]||0);if(n>0)rows.push('Poção '+k.toUpperCase()+' ×'+n);}for(const [key,value] of Object.entries(p.materials||{})){const n=value-(before.materials[key]||0);if(n>0)(/Soberano|Extensor|Origem/.test(key)?rare:rows).push(key+' ×'+n);}return [...rows,...rare,...equipment];}
